/**
 * An attribute value stores the value of an attribute definition for a specific entity.
 * Each attribute value references its definition and the entity it belongs to.
 */
export interface AttributeValue extends AttributeValueValueOneOf {
  /**
   * Value for STRING-type attribute. Must be in StringConfig.allowed_values.
   * @maxLength 40
   */
  stringData?: string;
  /** Value for NUMBER-type attribute. Must be within NumberConfig [min, max]. */
  numberData?: number;
  /** Value for BOOL-type attribute. */
  boolData?: boolean;
  /**
   * Attribute value ID.
   * @format GUID
   * @readonly
   */
  id?: string;
  /**
   * Revision number, which increments by 1 each time the attribute value is updated.
   * @readonly
   */
  revision?: string | null;
  /**
   * Date and time the attribute value was created.
   * @readonly
   */
  createdDate?: Date | null;
  /**
   * Date and time the attribute value was last updated.
   * @readonly
   */
  updatedDate?: Date | null;
  /**
   * ID of the attribute definition this value belongs to.
   * @format GUID
   * @readonly
   */
  attributeDefinitionId?: string;
  /**
   * Optional ID of the group this value is scoped to. Empty when the value is attached directly to an entity.
   * @internal
   * @format GUID
   * @readonly
   */
  groupId?: string | null;
  /**
   * ID of the entity this value belongs to. An entity is any resource your application owns
   * (in the current Rentals integration, a Bookings resource); this API does not validate it.
   * Use the same ID passed to `BulkUpsertAttributeValues` and `ListEntityAttributes`.
   * @format GUID
   * @readonly
   */
  entityId?: string;
  /**
   * Value type of this attribute. Matches the related attribute definition's value_type.
   * Set on create and never changes.
   * @readonly
   */
  valueType?: ValueTypeWithLiterals;
  /**
   * Custom field data for the attribute value.
   * [Extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields) must be configured in the app dashboard before they can be accessed with API calls.
   */
  extendedFields?: ExtendedFields;
}

/** @oneof */
export interface AttributeValueValueOneOf {
  /**
   * Value for STRING-type attribute. Must be in StringConfig.allowed_values.
   * @maxLength 40
   */
  stringData?: string;
  /** Value for NUMBER-type attribute. Must be within NumberConfig [min, max]. */
  numberData?: number;
  /** Value for BOOL-type attribute. */
  boolData?: boolean;
}

/** Value type of an attribute. */
export enum ValueType {
  /** String attribute: single-select from a predefined list of allowed string values. */
  STRING = 'STRING',
  /** Integer number attribute with a required min/max range. */
  NUMBER = 'NUMBER',
  /** Boolean attribute (true/false). */
  BOOL = 'BOOL',
}

/** @enumType */
export type ValueTypeWithLiterals = ValueType | 'STRING' | 'NUMBER' | 'BOOL';

export interface ExtendedFields {
  /**
   * Extended field data. Each key corresponds to the namespace of the app that created the extended fields.
   * The value of each key is structured according to the schema defined when the extended fields were configured.
   *
   * You can only access fields for which you have the appropriate permissions.
   *
   * Learn more about [extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields).
   */
  namespaces?: Record<string, Record<string, any>>;
}

export interface BulkUpsertAttributeValuesRequest {
  /**
   * ID of the entity whose attribute values to update.
   * @format GUID
   */
  entityId: string;
  /**
   * Optional ID of the group the entity belongs to. Stored on each resulting attribute value when provided.
   * @internal
   * @format GUID
   */
  groupId?: string | null;
  /**
   * Attribute values to upsert for this entity. Each entry is matched by `attribute_definition_id`.
   * Values not listed aren't modified.
   * @minSize 1
   * @maxSize 50
   */
  values?: BulkUpsertAttributeValue[];
  /** Whether to return the upserted attribute values in the response. */
  returnEntity?: boolean;
}

/**
 * Input for a single attribute value update.
 * entity_id and group_id are provided at the request level.
 */
export interface BulkUpsertAttributeValue
  extends BulkUpsertAttributeValueValueOneOf {
  /**
   * Value for STRING-type attribute. Must be in StringConfig.allowed_values.
   * @maxLength 40
   */
  stringData?: string;
  /** Value for NUMBER-type attribute. Must be within NumberConfig [min, max]. */
  numberData?: number;
  /** Value for BOOL-type attribute. */
  boolData?: boolean;
  /**
   * ID of the attribute definition this value applies to.
   * @format GUID
   */
  attributeDefinitionId?: string;
}

/** @oneof */
export interface BulkUpsertAttributeValueValueOneOf {
  /**
   * Value for STRING-type attribute. Must be in StringConfig.allowed_values.
   * @maxLength 40
   */
  stringData?: string;
  /** Value for NUMBER-type attribute. Must be within NumberConfig [min, max]. */
  numberData?: number;
  /** Value for BOOL-type attribute. */
  boolData?: boolean;
}

export interface BulkUpsertAttributeValuesResponse {
  /**
   * Upsert results, one per requested value, in request order.
   * @minSize 1
   * @maxSize 50
   */
  results?: BulkUpsertAttributeValueResult[];
  /** Bulk action metadata (success and failure counts). */
  bulkActionMetadata?: BulkActionMetadata;
}

export enum BulkActionType {
  INSERT = 'INSERT',
  UPDATE = 'UPDATE',
  DELETE = 'DELETE',
}

/** @enumType */
export type BulkActionTypeWithLiterals =
  | BulkActionType
  | 'INSERT'
  | 'UPDATE'
  | 'DELETE';

export interface ItemMetadata {
  /**
   * Item ID. Provided only whenever possible. For example, `itemId` can't be provided when item creation has failed.
   * @format GUID
   */
  id?: string | null;
  /** Index of the item within the request array. Allows for correlation between request and response items. */
  originalIndex?: number;
  /** Whether the requested action for this item was successful. When `false`, the `error` field is returned. */
  success?: boolean;
  /** Details about the error in case of failure. */
  error?: ApplicationError;
}

export interface ApplicationError {
  /** Error code. */
  code?: string;
  /** Description of the error. */
  description?: string;
  /** Data related to the error. */
  data?: Record<string, any> | null;
}

export interface BulkUpsertAttributeValueResult {
  /** Whether the value was inserted or updated. */
  action?: BulkActionTypeWithLiterals;
  /** Per-item metadata (id, original index, success). */
  itemMetadata?: ItemMetadata;
  /** The upserted value. Only returned when `return_entity` is `true` in the request. */
  item?: AttributeValue;
}

export interface BulkActionMetadata {
  /** Number of items that were successfully processed. */
  totalSuccesses?: number;
  /** Number of items that couldn't be processed. */
  totalFailures?: number;
  /** Number of failures without details because detailed failure threshold was exceeded. */
  undetailedFailures?: number;
}

export interface BulkDeleteAttributeValuesRequest {
  /**
   * ID of the entity whose attribute values to delete.
   * @format GUID
   */
  entityId: string;
  /**
   * IDs of the attribute definitions whose values should be removed from this entity.
   * @format GUID
   * @minSize 1
   * @maxSize 50
   */
  attributeDefinitionIds: string[];
}

export interface BulkDeleteAttributeValuesResponse {
  /**
   * Delete results, one per requested attribute definition, in request order.
   * @minSize 1
   * @maxSize 50
   */
  results?: BulkDeleteAttributeValueResult[];
  /** Bulk action metadata (success and failure counts). */
  bulkActionMetadata?: BulkActionMetadata;
}

export interface BulkDeleteAttributeValueResult {
  /** Per-item metadata (deleted value id, original index, success). */
  itemMetadata?: ItemMetadata;
}

export interface ListEntityAttributesRequest {
  /**
   * ID of the entity whose attributes to retrieve.
   * @format GUID
   */
  entityId: string;
  /**
   * Optional, currently ignored. Results include all of the entity's values regardless of group.
   * @internal
   * @format GUID
   */
  groupId?: string | null;
  /** Cursor-based paging. */
  paging?: CursorPaging;
}

export interface CursorPaging {
  /**
   * Maximum number of items to return in the results.
   * @max 100
   */
  limit?: number | null;
  /**
   * Pointer to the next or previous page in the list of results.
   *
   * Pass the relevant cursor token from the `pagingMetadata` object in the previous call's response.
   * Not relevant for the first request.
   * @maxLength 16000
   */
  cursor?: string | null;
}

export interface ListEntityAttributesResponse {
  /**
   * The entity's attribute values, each paired with its attribute definition. Order isn't guaranteed.
   * @maxSize 50
   */
  entityAttributes?: EntityAttribute[];
  /** Paging metadata. */
  pagingMetadata?: CursorPagingMetadata;
}

/**
 * An attribute definition paired with its current attribute value for a specific entity.
 * Used to display attribute name, type, and value together without making separate calls.
 */
export interface EntityAttribute {
  /** The attribute definition. */
  attributeDefinition?: AttributeDefinition;
  /** The entity's value for this attribute. */
  attributeValue?: AttributeValue;
}

/**
 * An attribute definition is a typed custom property (string, number, or boolean) that can be
 * applied to entities. Each definition has a display name shown to end users, a value type,
 * optional type-specific configuration (such as a list of allowed string values), and a
 * default value.
 *
 * Attribute definitions are defined once per site. To set a value for a specific entity,
 * call Bulk Upsert Attribute Values; to read an entity's values together with their
 * definitions, call List Entity Attributes.
 */
export interface AttributeDefinition extends AttributeDefinitionConfigOneOf {
  /** String configuration: the list of allowed string values. */
  stringConfig?: StringConfig;
  /** Number configuration: the valid integer range. */
  numberConfig?: NumberConfig;
  /**
   * Attribute definition ID.
   * @format GUID
   * @readonly
   */
  id?: string;
  /**
   * Revision number, which increments by 1 each time the attribute definition is updated.
   * To prevent conflicting changes, the current revision must be passed when updating.
   * Ignored when creating an attribute definition.
   * @readonly
   */
  revision?: string | null;
  /**
   * Date and time the attribute definition was created.
   * @readonly
   */
  createdDate?: Date | null;
  /**
   * Date and time the attribute definition was last updated.
   * @readonly
   */
  updatedDate?: Date | null;
  /**
   * Display name for the attribute, shown to end users (for example, `Capacity`).
   *
   * Must be unique within the site. Required when creating an attribute definition.
   * @maxLength 40
   * @minLength 1
   */
  name?: string | null;
  /**
   * Value type of this attribute.
   * Immutable after creation. `UpdateAttributeDefinition` rejects requests that change `value_type`.
   * Required when creating an attribute definition.
   */
  valueType?: ValueTypeWithLiterals;
  /**
   * Whether this attribute is shown to end users on the public site.
   *
   * - `true`: shown in the UI and available for filtering.
   * - `false`: hidden from end users. Back-office admins can still see and edit the attribute.
   *
   * Default: `true`.
   */
  visibility?: boolean | null;
  /**
   * Default value for the attribute. When a configuration change leaves a stored
   * attribute value out of range or outside the allowed values, that value is reset to this
   * default (see Update Attribute Definition).
   *
   * The variant must match `valueType`. Required when creating an attribute definition.
   */
  defaultValue?: AttributeDefaultValue;
  /**
   * Internal, legacy. IDs of the groups this attribute is associated with. Not part of the
   * per-site definition / per-entity value model.
   * @internal
   * @format GUID
   * @readonly
   * @maxSize 100
   */
  groupIds?: string[];
  /**
   * Custom field data for the attribute definition.
   * [Extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields) must be configured in the app dashboard before they can be accessed with API calls.
   */
  extendedFields?: ExtendedFields;
  /**
   * Custom tags for organizing and filtering attribute definitions.
   * Manage tags using `BulkUpdateAttributeDefinitionTags` or `BulkUpdateAttributeDefinitionTagsByFilter`.
   */
  tags?: Tags;
}

/** @oneof */
export interface AttributeDefinitionConfigOneOf {
  /** String configuration: the list of allowed string values. */
  stringConfig?: StringConfig;
  /** Number configuration: the valid integer range. */
  numberConfig?: NumberConfig;
}

/** Configuration for STRING-type attributes. */
export interface StringConfig {
  /**
   * Allowed string values for this attribute. Values can be added, removed, or renamed; on update, any entity value
   * that no longer matches the allowed values is reset to the attribute's default.
   * @minSize 1
   * @maxSize 50
   * @maxLength 40
   */
  allowedValues?: string[];
}

/**
 * Configuration for NUMBER-type attributes. Defines the valid range of integer values.
 * On update, any entity value that falls outside the range is reset to the attribute's default.
 */
export interface NumberConfig {
  /** Minimum allowed value (integer). */
  min?: number;
  /** Maximum allowed value (integer). Must be greater than or equal to `min`. */
  max?: number;
}

/** Default value for an attribute. Exactly one variant is set, matching the attribute's value_type. */
export interface AttributeDefaultValue extends AttributeDefaultValueValueOneOf {
  /**
   * Default value for a STRING-type attribute. Must be in StringConfig.allowed_values.
   * @maxLength 40
   */
  stringDefault?: string;
  /** Default value for a NUMBER-type attribute. Must be within NumberConfig [min, max]. */
  numberDefault?: number;
  /** Default value for a BOOL-type attribute. */
  boolDefault?: boolean;
}

/** @oneof */
export interface AttributeDefaultValueValueOneOf {
  /**
   * Default value for a STRING-type attribute. Must be in StringConfig.allowed_values.
   * @maxLength 40
   */
  stringDefault?: string;
  /** Default value for a NUMBER-type attribute. Must be within NumberConfig [min, max]. */
  numberDefault?: number;
  /** Default value for a BOOL-type attribute. */
  boolDefault?: boolean;
}

/**
 * Common object for tags.
 * Should be use as in this example:
 * message Foo {
 * option (.wix.api.decomposite_of) = "wix.commons.v2.tags.Foo";
 * string id = 1;
 * ...
 * Tags tags = 5
 * }
 *
 * example of taggable entity
 * {
 * id: "123"
 * tags: {
 * public_tags: {
 * tag_ids:["11","22"]
 * },
 * private_tags: {
 * tag_ids: ["33", "44"]
 * }
 * }
 * }
 */
export interface Tags {
  /** Tags that require an additional permission in order to access them, normally not given to site members or visitors. */
  privateTags?: TagList;
  /** Tags that are exposed to anyone who has access to the labeled entity itself, including site members and visitors. */
  publicTags?: TagList;
}

export interface TagList {
  /**
   * List of tag IDs.
   * @maxSize 100
   * @maxLength 5
   */
  tagIds?: string[];
}

export interface CursorPagingMetadata {
  /** Number of items returned in current page. */
  count?: number | null;
  /** Cursor strings that point to the next page, previous page, or both. */
  cursors?: Cursors;
  /**
   * Whether there are more pages to retrieve following the current page.
   *
   * + `true`: Another page of results can be retrieved.
   * + `false`: This is the last page.
   */
  hasNext?: boolean | null;
}

export interface Cursors {
  /**
   * Cursor string pointing to the next page in the list of results.
   * @maxLength 16000
   */
  next?: string | null;
  /**
   * Cursor pointing to the previous page in the list of results.
   * @maxLength 16000
   */
  prev?: string | null;
}

export interface QueryAttributeValuesRequest {
  /** WQL expression. */
  query?: CursorQuery;
}

export interface CursorQuery extends CursorQueryPagingMethodOneOf {
  /**
   * Cursor paging options.
   *
   * Learn more about [cursor paging](https://dev.wix.com/docs/rest/articles/getting-started/api-query-language#cursor-paging).
   */
  cursorPaging?: CursorPaging;
  /**
   * Filter object.
   *
   * Learn more about the [filter section](https://dev.wix.com/docs/rest/articles/getting-started/api-query-language#the-filter-section).
   */
  filter?: Record<string, any> | null;
  /**
   * Sort object.
   *
   * Learn more about the [sort section](https://dev.wix.com/docs/rest/articles/getting-started/api-query-language#the-sort-section).
   * @maxSize 5
   */
  sort?: Sorting[];
}

/** @oneof */
export interface CursorQueryPagingMethodOneOf {
  /**
   * Cursor paging options.
   *
   * Learn more about [cursor paging](https://dev.wix.com/docs/rest/articles/getting-started/api-query-language#cursor-paging).
   */
  cursorPaging?: CursorPaging;
}

export interface Sorting {
  /**
   * Name of the field to sort by.
   * @maxLength 512
   */
  fieldName?: string;
  /** Sort order. */
  order?: SortOrderWithLiterals;
}

export enum SortOrder {
  ASC = 'ASC',
  DESC = 'DESC',
}

/** @enumType */
export type SortOrderWithLiterals = SortOrder | 'ASC' | 'DESC';

export interface QueryAttributeValuesResponse {
  /**
   * Matching attribute values.
   * @maxSize 1000
   */
  attributeValues?: AttributeValue[];
  /** Paging metadata. */
  pagingMetadata?: CursorPagingMetadata;
}

/** @docsIgnore */
export type BulkUpsertAttributeValuesApplicationErrors =
  | {
      code?: 'VALUE_REQUIRED';
      description?: string;
      data?: Record<string, any>;
    }
  | {
      code?: 'VALUE_TYPE_MISMATCH';
      description?: string;
      data?: Record<string, any>;
    }
  | {
      code?: 'VALUE_NOT_IN_ALLOWED_VALUES';
      description?: string;
      data?: Record<string, any>;
    }
  | {
      code?: 'VALUE_OUT_OF_RANGE';
      description?: string;
      data?: Record<string, any>;
    }
  | {
      code?: 'ATTRIBUTE_DEFINITION_NOT_FOUND';
      description?: string;
      data?: Record<string, any>;
    };
